changeSet.sql:
DELETE FROM reaction WHERE answer_post_id IN ( SELECT ap.id FROM answer_post ap WHERE ap.post_id IN ( SELECT p.id FROM post p WHERE p.conversation_id IN (SELECT c.id FROM conversation c JOIN exercise e ON e.id = c.exercise_id WHERE c.course_id IS NULL AND e.course_id IS NULL AND NOT EXISTS (SELECT 1 FROM tutorial_group tg WHERE tg.tutorial_group_channel_id = c.id))));
DELETE FROM reaction WHERE post_id IN ( SELECT p.id FROM post p WHERE p.conversation_id IN (SELECT c.id FROM conversation c JOIN exercise e ON e.id = c.exercise_id WHERE c.course_id IS NULL AND e.course_id IS NULL AND NOT EXISTS (SELECT 1 FROM tutorial_group tg WHERE tg.tutorial_group_channel_id = c.id)));
DELETE FROM answer_post WHERE post_id IN ( SELECT p.id FROM post p WHERE p.conversation_id IN (SELECT c.id FROM conversation c JOIN exercise e ON e.id = c.exercise_id WHERE c.course_id IS NULL AND e.course_id IS NULL AND NOT EXISTS (SELECT 1 FROM tutorial_group tg WHERE tg.tutorial_group_channel_id = c.id)));
DELETE FROM post WHERE conversation_id IN (SELECT c.id FROM conversation c JOIN exercise e ON e.id = c.exercise_id WHERE c.course_id IS NULL AND e.course_id IS NULL AND NOT EXISTS (SELECT 1 FROM tutorial_group tg WHERE tg.tutorial_group_channel_id = c.id));
DELETE FROM conversation_participant WHERE conversation_id IN (SELECT c.id FROM conversation c JOIN exercise e ON e.id = c.exercise_id WHERE c.course_id IS NULL AND e.course_id IS NULL AND NOT EXISTS (SELECT 1 FROM tutorial_group tg WHERE tg.tutorial_group_channel_id = c.id));
DELETE FROM conversation WHERE course_id IS NULL AND exercise_id IN (SELECT id FROM exercise WHERE course_id IS NULL) AND NOT EXISTS (SELECT 1 FROM tutorial_group tg WHERE tg.tutorial_group_channel_id = conversation.id);

UPDATE conversation SET course_id = (
    SELECT e.course_id FROM exercise e WHERE e.id = conversation.exercise_id
)
WHERE course_id IS NULL AND exercise_id IS NOT NULL;

UPDATE conversation SET course_id = (
    SELECT l.course_id FROM lecture l WHERE l.id = conversation.lecture_id
)
WHERE course_id IS NULL AND lecture_id IS NOT NULL;

UPDATE conversation SET course_id = (
    SELECT ex.course_id FROM exam ex WHERE ex.id = conversation.exam_id
)
WHERE course_id IS NULL AND exam_id IS NOT NULL;
